const data = $input.item.json.body || $input.item.json;

// --- 1. DATENVALIDIERUNG ---
const ingredients = data.ingredients;
const preferences = data.preferences;

if (!ingredients || !Array.isArray(ingredients) || ingredients.length === 0) {
  return { json: { allowed: false, status: 400, message: "Ungültige Daten: 'ingredients' fehlt oder ist leer." } };
}

if (!preferences || typeof preferences.portions !== 'number' || typeof preferences.persons !== 'number') {
  return { json: { allowed: false, status: 400, message: "Ungültige Daten: 'portions' oder 'persons' fehlerhaft." } };
}

// --- 2. QUOTA-MANAGEMENT ---
const staticData = $getWorkflowStaticData('global');
const today = new Date().toISOString().split('T')[0];
const SYSTEM_QUOTA = 100;
const IP_QUOTA = 12;

if (staticData.date !== today) {
  staticData.date = today;
  staticData.systemCount = 0;
  staticData.ipCounts = {};
}

const headers = $input.item.headers || {};
let clientIp = headers['x-forwarded-for'] || headers['x-real-ip'] || headers['host'] || 'unknown';
if (clientIp.includes(',')) {
  clientIp = clientIp.split(',')[0].trim();
}

const currentIpCount = staticData.ipCounts[clientIp] || 0;

if (staticData.systemCount >= SYSTEM_QUOTA) {
  return { json: { allowed: false, status: 429, message: "System-weite Quota von 100 Rezepten pro Tag erreicht." } };
}

if (currentIpCount >= IP_QUOTA) {
  return { json: { allowed: false, status: 429, message: `Dein IP-Limit ist erreicht. Du kannst maximal ${IP_QUOTA} Rezepte pro Tag generieren.` } };
}

staticData.systemCount++;
staticData.ipCounts[clientIp] = currentIpCount + 1;

return { json: { allowed: true, data: data } };

