const staticData = $getWorkflowStaticData('global');
const today = new Date().toISOString().split('T')[0];
const SYSTEM_QUOTA = 100;
const IP_QUOTA = 12;

if (staticData.date !== today) {
  staticData.date = today;
  staticData.systemCount = 0;
  staticData.ipCounts = {};
}

const headers = $input.item.headers || {};
let clientIp = headers['x-forwarded-for'] || headers['x-real-ip'] || headers['host'] || 'unknown';
if (clientIp.includes(',')) {
  clientIp = clientIp.split(',')[0].trim();
}

const currentIpCount = staticData.ipCounts[clientIp] || 0;

return {
  json: {
    systemQuota: SYSTEM_QUOTA,
    systemUsed: staticData.systemCount || 0,
    systemRemaining: Math.max(0, SYSTEM_QUOTA - (staticData.systemCount || 0)),
    ipQuota: IP_QUOTA,
    ipUsed: currentIpCount,
    ipRemaining: Math.max(0, IP_QUOTA - currentIpCount)
  }
};
